/* ---------- utilidades ---------- */
const precioFinal=(neto,iva)=>r2(neto*(1+(iva==null?21:iva)/100));
const srvOf=id=>DB.servicios.find(s=>s.id===id);
const cliByTel=t=>{const k=tel10(t);return k.length>=8?DB.clientes.find(c=>tel10(c.tel)===k):null};
const edad=n=>{if(!n)return 0;const d=new Date(n+'T00:00:00'),h=new Date();let a=h.getFullYear()-d.getFullYear();const m=h.getMonth()-d.getMonth();if(m<0||(m===0&&h.getDate()<d.getDate()))a--;return a};
const socioNum=c=>'N.º '+String(c.socio||0).padStart(4,'0');
function nivelOf(c){const N=DB.cfg.club.niveles.slice().sort((a,b)=>a.d-b.d),acum=ptsAcum(c);let lv=N[0],nx=null;N.forEach((n,i)=>{if(acum>=n.d){lv=n;nx=N[i+1]||null}});return{lv,nx,acum}}
function ptsAcum(c){return DB.ptsMov.filter(m=>m.cliId===c.id&&m.pts>0&&m.tipo!=='Ajuste').reduce((a,m)=>a+m.pts,0)}
const ptsPesos=p=>r2((p||0)*DB.cfg.club.valor);
function ptsMov(c,tipo,pts,ref){pts=Math.round(pts);if(!pts)return;c.pts=Math.max(0,(c.pts||0)+pts);DB.ptsMov.unshift({id:uid('pm'),cliId:c.id,fecha:TODAY(),tipo,pts,ref:ref||'',u:ME?ME.n:'menú'});if(DB.ptsMov.length>3000)DB.ptsMov.length=3000}
function clubAcum(c,monto,ref){const K=DB.cfg.club;if(!K.on||!c||!c.club||!(monto>0))return 0;const p=Math.floor(monto/K.cada)*K.ptsx;if(p>0){ptsMov(c,'Acumulación',p,ref);audit('Club: puntos acumulados',c.n+' +'+p+' · '+ref)}return p}
function hacerSocio(c,nac){if(c.club)return;c.club=true;if(nac)c.nac=nac;DB.seq.socio=(DB.seq.socio||0)+1;c.socio=DB.seq.socio;audit('Club: socio nuevo',c.n+' · '+socioNum(c))}
const waLink=(tel,msg)=>wa(tel,msg);
function stockTag(r){return r.qty<=0?'<span class="tag bad">Sin stock</span>':r.qty<=r.alarma?'<span class="tag warn">Últimas unidades</span>':'<span class="tag ok">Disponible</span>'}

/* ---------- recursos, permisos y navegación ---------- */
if(!RECURSOS.includes('Box instalaciones (audio · alarmas)'))RECURSOS.push('Box instalaciones (audio · alarmas)');
['jefe','recepcion'].forEach(r=>{['webp','club','garant'].forEach(v=>{if(PERM[r].indexOf(v)<0)PERM[r].push(v)})});
(function(){const ix=NAV.findIndex(n=>n[0]==='turnos');NAV.splice(ix+1,0,['webp','🌐','Menú digital y pedidos']);const iy=NAV.findIndex(n=>n[0]==='clientes');NAV.splice(iy+1,0,['club','⭐','Club y fidelización'],['garant','🛡️','Garantías'])})();
const _renderShell=renderShell;renderShell=function(){_renderShell();const nw=DB.pedidos.filter(p=>p.estado==='Nuevo').length+DB.solic.filter(s=>s.estado==='Nueva').length;const b=$('#nav_webp');if(b&&nw)b.insertAdjacentHTML('beforeend','<span class="badge2">'+nw+'</span>');
 const nav=$('#side nav');if(nav)nav.insertAdjacentHTML('beforeend','<a class="navmenu" href="'+menuHash()+'" target="_blank" rel="noopener" style="display:flex;gap:10px;align-items:center;padding:10px 14px;color:#cfd3d9;text-decoration:none;border-top:1px solid #333;margin-top:6px"><span aria-hidden="true">📱</span>Ver menú digital (público)</a>')};

/* ---------- alertas extra (avisos) ---------- */
const _alertas=alertas;alertas=function(){const A=_alertas();if(!DB.garantias)return A;
 const nw=DB.pedidos.filter(p=>p.estado==='Nuevo').length,ns=DB.solic.filter(s=>s.estado==='Nueva').length;
 if(nw)A.unshift({t:'ok',x:nw+' pedido(s) nuevo(s) del menú digital',go:'webp'});if(ns)A.unshift({t:'ok',x:ns+' turno(s) pedido(s) por el menú digital para confirmar',go:'webp'});
 const gv=DB.garantias.filter(g=>{const d=daysTo(g.hasta);return d>=0&&d<=30}).length;if(gv)A.push({t:'ok',x:gv+' garantía(s) vencen en los próximos 30 días',go:'garant'});
 const mes=TODAY().slice(5,7),cm=DB.clientes.filter(c=>c.club&&c.nac&&c.nac.slice(5,7)===mes).length;if(cm)A.push({t:'ok',x:cm+' socio(s) del Club cumplen años este mes',go:'club'});return A};

/* ---------- panel: indicadores del menú y del Club ---------- */
const _dash=V.dash;V.dash=()=>{let s=_dash();if(ME.rol==='mecanico'||ME.rol==='limpieza')return s;
 const k=(v,l,g,cls)=>'<button class="kpi '+(cls||'')+'" data-act="go" data-v="'+g+'"><div class="v">'+v+'</div><div class="l">'+l+'</div></button>';
 const nw=DB.pedidos.filter(p=>p.estado==='Nuevo').length,ns=DB.solic.filter(x=>x.estado==='Nueva').length,so=DB.clientes.filter(c=>c.club).length,gv=DB.garantias.filter(g=>daysTo(g.hasta)>=0).length;
 const row='<div class="g4" style="margin-bottom:14px">'+k(nw,'Pedidos nuevos del menú digital','webp',nw?'bad':'')+k(ns,'Turnos web por confirmar','webp',ns?'bad':'')+k(so,'Socios del Club','club','okk')+k(gv,'Garantías vigentes','garant')+'</div>';
 const i=s.indexOf('<div class="g2">');return i>0?s.slice(0,i)+row+s.slice(i):s+row};

/* ---------- OT: área de trabajo y checklist de instalaciones ---------- */
const INSTCK=[['bat','Batería y carga OK'],['tab','Tablero sin testigos encendidos'],['vid','Levantavidrios y cierre funcionan'],['aud','Audio original funciona'],['cer','Llaves y controles recibidos']];
function otAreaHTML(){return '<div class="g2"><div class="f"><label for="n_area">Tipo de trabajo</label><select id="n_area" data-chg="otarea">'+opts(AREAS,'mec',a=>[a[0],a[2]+' '+a[1]])+'</select></div><div class="f sm mut" style="align-self:end">Las instalaciones (audio, alarmas, electricidad, accesorios) suman el control eléctrico previo y van al box de instalaciones.</div></div>'+
 '<div id="n_inst" class="card" style="background:#fff8e6;border-color:#f3d48a" hidden><h3>Estado eléctrico previo (instalaciones)</h3><div class="g3">'+INSTCK.map(c=>'<label style="font-weight:500;color:var(--tx)"><input type="checkbox" id="n_ci_'+c[0]+'" style="width:auto;min-height:0" checked> '+c[1]+'</label>').join('')+'</div><p class="sm mut" style="margin:6px 0 0">Lo que no funcione al recibir el vehículo queda anotado y se imprime en la orden.</p></div>'}
CHG.otarea=t=>{const i=$('#n_inst');if(i)i.hidden=!AREA_INST.includes(t.value);const r=$('#n_rec');if(r&&AREA_INST.includes(t.value)&&!r.value)r.value=String(RECURSOS.length-1)};
function otAreaRead(o){o.area=val('n_area')||'mec';if(AREA_INST.includes(o.area)){o.check=o.check||{};o.check.inst={};INSTCK.forEach(c=>{o.check.inst[c[0]]=chk('n_ci_'+c[0])})}}
const otAreaBadge=o=>{const a=areaOf(o.area);return '<span class="badge" title="'+h(a[1])+'">'+a[2]+' '+h(a[1])+'</span>'};
const instPrint=o=>{const i=o.check&&o.check.inst;if(!i)return '';return '<p class="sm">Estado eléctrico previo: '+INSTCK.map(c=>c[1]+': '+(i[c[0]]?'OK':'NO / revisar')).join(' · ')+'</p>'};

/* ---------- garantías al entregar + puntos del Club ---------- */
const _finEntrega=finEntrega;finEntrega=function(o){_finEntrega(o);try{extEntrega(o)}catch(e){console.warn(e)}};
function extEntrega(o){const c=cliOf(o.cliId),t=otTotal(o);
 const pp=(o.pagos||[]).filter(p=>p.medio==='Puntos del Club').reduce((a,p)=>a+p.monto,0);clubAcum(c,r2(t.total-pp),otNum(o));
 (o.items||[]).forEach(i=>{let m=0;if(i.k==='mo'){const s=srvOf(i.sid)||DB.servicios.find(x=>x.n===i.desc);m=s?s.gar:0}else if(i.k==='rep'){const r=repOf(i.repId);m=r?r.gar:0}
  if(m>0)DB.garantias.unshift({id:uid('ga'),otId:o.id,cliId:o.cliId,vehId:o.vehId,desc:i.desc,desde:TODAY(),hasta:addDays(Math.round(m*30.4)),serie:'',recl:[]})})}
const _vtcobrar=ACT.vtcobrar;ACT.vtcobrar=d=>{const n0=(DB.ventas||[]).length;_vtcobrar(d);if((DB.ventas||[]).length>n0){const v=DB.ventas[0];const c=cliOf(v.cliId);const p=clubAcum(c,v.total,'VT-'+String(v.num).padStart(4,'0'));
 (v.lines||[]).forEach(l=>{if(l.k!=='rep')return;const r=repOf(l.repId);if(r&&r.gar>0&&c)DB.garantias.unshift({id:uid('ga'),otId:'',vtId:v.id,cliId:c.id,vehId:'',desc:l.desc,desde:TODAY(),hasta:addDays(Math.round(r.gar*30.4)),serie:'',recl:[]})});
 save();if(p>0)setTimeout(()=>toast(c.n+' sumó '+p+' puntos del Club'),900)}};
/* canje de puntos como medio de pago al entregar la OT */
function ptsDispHTML(o){const c=cliOf(o.cliId);if(!c||!c.club||!DB.cfg.club.on||!(c.pts>0))return '';return '<div class="f"><label for="pg_pt">Canje de puntos del Club ('+c.pts+' pts = hasta '+fmt(ptsPesos(c.pts))+')</label><input id="pg_pt" inputmode="decimal" data-chg="pgcalc" placeholder="0,00"></div>'}

/* ======================= Menú digital y pedidos (sistema) ======================= */
UI.webTab=UI.webTab||'ped';
V.webp=()=>{const T=UI.webTab;const nw=DB.pedidos.filter(p=>p.estado==='Nuevo').length,ns=DB.solic.filter(s=>s.estado==='Nueva').length;
 const tabs=[['ped','Pedidos del menú'+(nw?' ('+nw+')':'')],['sol','Turnos pedidos'+(ns?' ('+ns+')':'')],['srv','Catálogo de servicios'],['prd','Productos publicados'],['cfg','Configurar menú']];
 let b='';if(T==='ped')b=webPedHTML();else if(T==='sol')b=webSolHTML();else if(T==='srv')b=webSrvHTML();else if(T==='prd')b=webPrdHTML();else b=webCfgHTML();
 return '<div class="bar"><h2>Menú digital y pedidos</h2><span class="sp"></span><a class="btn p" href="'+menuHash()+'" target="_blank" rel="noopener">📱 Abrir el menú público</a><button class="btn" data-act="webshare">💬 Compartir por WhatsApp</button><button class="btn" data-act="webcopy">🔗 Copiar enlace</button></div>'+
 '<div class="demoflag" style="background:#eef6ff;border-color:#b9d6f7;color:#12406f">Lo que los clientes piden desde el menú queda guardado en el navegador donde se hizo el pedido y además llega por WhatsApp al taller. Con la nube del Sistema VB los pedidos llegan solos a todos los equipos del taller.</div>'+
 '<div class="chips" style="margin-bottom:10px">'+tabs.map(t=>'<button class="chip'+(T===t[0]?' on':'')+'" data-act="webtab" data-t="'+t[0]+'">'+t[1]+'</button>').join('')+'</div>'+b};
ACT.webtab=d=>{UI.webTab=d.t;renderView()};
const menuHash=()=>VB_CLIENTE?(MODO==='real'?'#menu':'#practica-menu'):(MODO==='real'?'#real-menu':'#menu');
const sysHash=()=>VB_CLIENTE?(MODO==='real'?'':'#practica'):(MODO==='real'?'#real':'');
const menuURL=()=>location.href.split('#')[0]+menuHash();
ACT.webcopy=()=>{const u=menuURL();try{navigator.clipboard.writeText(u).then(()=>toast('Enlace copiado'),()=>prompt('Copiá el enlace:',u))}catch(e){prompt('Copiá el enlace:',u)}};
ACT.webshare=()=>window.open('https://wa.me/?text='+encodeURIComponent('Mirá nuestros servicios y productos, pedí turno y sumate al Club de '+DB.cfg.nombre+': '+menuURL()),'_blank','noopener');
function webPedHTML(){const L=DB.pedidos.slice().sort((a,b)=>b.t-a.t);if(!L.length)return '<p class="mut">Todavía no hay pedidos del menú digital.</p>';
 return L.map(p=>{const tot=p.items.reduce((a,i)=>a+i.qty*i.pu,0),hasRep=p.items.some(i=>i.k==='rep'),hasSrv=p.items.some(i=>i.k==='srv');
  return '<div class="card"><div class="row"><b>Pedido web N.º '+String(p.num).padStart(4,'0')+'</b><span class="badge '+(p.estado==='Nuevo'?'warn':p.estado==='Descartado'?'':'ok')+'">'+p.estado+'</span><span class="sp"></span><span class="mut sm">'+ftime(p.t)+'</span></div>'+
  '<p style="margin:6px 0"><b>'+h(p.n)+'</b> · '+h(p.tel)+(p.veh?' · '+h(p.veh):'')+' · '+(p.entrega==='instalar'?'<b>Quiere que se lo instalen</b>':'Retira en el local')+'</p>'+
  '<div class="tw"><table class="itbl"><tbody>'+p.items.map(i=>'<tr><td>'+(i.k==='srv'?'🧰 ':'📦 ')+h(i.desc)+'</td><td class="n">'+i.qty+' ×</td><td class="n">'+fmt(i.pu)+'</td><td class="n">'+fmt(i.qty*i.pu)+'</td></tr>').join('')+'</tbody></table></div>'+
  '<div class="row" style="margin-top:6px"><span class="mut sm">'+h(p.nota||'')+'</span><span class="sp"></span><b>Total estimado (con IVA) '+fmt(tot)+'</b></div>'+
  '<div class="row" style="margin-top:8px"><a class="btn s" target="_blank" rel="noopener" href="'+h(waLink(p.tel,'Hola '+p.n.split(' ')[0]+', recibimos tu pedido N.º '+String(p.num).padStart(4,'0')+' en '+DB.cfg.nombre+'. '))+'">💬 Responder</a>'+
  (hasRep&&p.estado!=='Convertido'?'<button class="btn s p" data-act="webped2vt" data-id="'+p.id+'">🛒 Pasar a venta</button>':'')+(hasSrv&&p.estado!=='Convertido'?'<button class="btn s" data-act="webped2tu" data-id="'+p.id+'">📅 Agendar turno</button>':'')+
  (p.estado==='Nuevo'?'<button class="btn s" data-act="webpedest" data-id="'+p.id+'" data-e="Atendido">✔ Atendido</button><button class="btn s" data-act="webpedest" data-id="'+p.id+'" data-e="Descartado">Descartar</button>':'')+'</div></div>'}).join('')}
ACT.webpedest=d=>{const p=DB.pedidos.find(x=>x.id===d.id);if(!p)return;p.estado=d.e;audit('Pedido web '+d.e.toLowerCase(),'N.º '+p.num);save();renderView();renderShellBadge()};
ACT.webped2vt=d=>{const p=DB.pedidos.find(x=>x.id===d.id);if(!p)return;const L=[];let falta='';
 p.items.filter(i=>i.k==='rep').forEach(i=>{const r=repOf(i.id);if(!r)return;if(r.qty<i.qty)falta=r.desc;L.push({k:'rep',repId:r.id,desc:r.desc+' ('+r.marca+')',qty:Math.min(i.qty,Math.max(r.qty,0))||i.qty,pu:r.pv,pu0:r.pv,iva:r.iva,costo:r.pc,dt:'%',dv:0})});
 const c=cliByTel(p.tel);UI.vt=Object.assign(UI.vt||{},{lines:L,sinIva:false,medio:'Efectivo',cli:c?c.id:'__new',cond:c?(c.cond||'CF'):'CF',doc:c?(c.doc||''):'',nc:{n:p.n.replace(/ \(ejemplo\)$/,''),tel:p.tel,prov:'Salta',lim:0}});
 p.estado='Convertido';audit('Pedido web pasado a venta','N.º '+p.num);save();go('ventas');renderShellBadge();toast('Pedido cargado en la venta de mostrador: revisá precios y cobrá.'+(falta?' Atención: falta stock de '+falta+'.':''),!!falta)};
ACT.webped2tu=d=>{const p=DB.pedidos.find(x=>x.id===d.id);if(!p)return;const s=p.items.find(i=>i.k==='srv');DB.seq.sol=(DB.seq.sol||0)+1;
 DB.solic.unshift({id:uid('sw'),num:DB.seq.sol,t:Date.now(),fecha:addDays(1),hora:9,sid:s?s.id:'',n:p.n,tel:p.tel,pat:'',veh:p.veh||'',nota:'Desde el pedido web N.º '+p.num+(p.nota?' · '+p.nota:''),estado:'Nueva'});
 p.estado='Atendido';save();UI.webTab='sol';renderView();toast('Se creó la solicitud de turno: completá patente, fecha y confirmala.')};
function renderShellBadge(){const nw=DB.pedidos.filter(p=>p.estado==='Nuevo').length+DB.solic.filter(s=>s.estado==='Nueva').length;const b=$('#nav_webp');if(!b)return;let x=b.querySelector('.badge2');if(!nw){if(x)x.remove();return}if(!x){b.insertAdjacentHTML('beforeend','<span class="badge2"></span>');x=b.querySelector('.badge2')}x.textContent=nw}
function webSolHTML(){const L=DB.solic.slice().sort((a,b)=>(a.estado==='Nueva'?0:1)-(b.estado==='Nueva'?0:1)||b.t-a.t);if(!L.length)return '<p class="mut">No hay turnos pedidos por el menú.</p>';
 return '<div class="tw"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Vehículo</th><th>Servicio</th><th>Día y hora pedidos</th><th>Estado</th><th></th></tr></thead><tbody>'+L.map(s=>{const sv=srvOf(s.sid);
  return '<tr><td>'+ftime(s.t)+'</td><td><b>'+h(s.n)+'</b><br><span class="sm mut">'+h(s.tel)+'</span></td><td>'+h(s.pat||'—')+'<br><span class="sm mut">'+h(s.veh||'')+'</span></td><td>'+(sv?areaOf(sv.area)[2]+' '+h(sv.n):'—')+(s.nota?'<br><span class="sm mut">'+h(s.nota)+'</span>':'')+'</td><td>'+fdate(s.fecha)+' · '+String(s.hora).padStart(2,'0')+':00</td><td><span class="badge '+(s.estado==='Nueva'?'warn':s.estado==='Confirmada'?'ok':'')+'">'+s.estado+'</span></td>'+
  '<td>'+(s.estado==='Nueva'?'<div class="row"><button class="btn s p" data-act="websolok" data-id="'+s.id+'">Confirmar</button><button class="btn s" data-act="websolno" data-id="'+s.id+'">Rechazar</button></div>':'<a class="btn s" target="_blank" rel="noopener" href="'+h(waLink(s.tel,'Hola '+s.n.split(' ')[0]+', te escribimos de '+DB.cfg.nombre+' por tu turno.'))+'">💬</a>')+'</td></tr>'}).join('')+'</tbody></table></div>'}
ACT.websolok=d=>{const s=DB.solic.find(x=>x.id===d.id);if(!s)return;const sv=srvOf(s.sid)||{n:'Servicio',h:1,area:'mec'};const inst=AREA_INST.includes(sv.area);const recs=inst?[RECURSOS.length-1]:RECURSOS.map((r,i)=>i).filter(i=>i<RECURSOS.length-1);
 modal({title:'Confirmar turno pedido por el menú',ok:'Confirmar y agendar',body:'<p><b>'+h(s.n)+'</b> · '+h(s.tel)+'<br>'+h(sv.n)+(s.nota?' · <span class="mut">'+h(s.nota)+'</span>':'')+'</p>'+
  '<div class="g4"><div class="f"><label for="ws_f">Fecha</label><input type="date" id="ws_f" value="'+s.fecha+'"></div><div class="f"><label for="ws_h">Hora</label><select id="ws_h">'+opts(HORAS,s.hora,x=>[x,String(x).padStart(2,'0')+':00'])+'</select></div><div class="f"><label for="ws_d">Duración (h)</label><select id="ws_d">'+opts([1,2,3,4,5,6],Math.max(1,Math.ceil(sv.h||1)))+'</select></div><div class="f"><label for="ws_r">Puesto</label><select id="ws_r">'+opts(RECURSOS.map((r,i)=>[i,r]),recs[0],x=>x)+'</select></div></div>'+
  '<div class="g3"><div class="f"><label for="ws_p">Patente</label><input id="ws_p" value="'+h(s.pat)+'" maxlength="8" placeholder="AB123CD"></div><div class="f"><label for="ws_m">Marca</label><input id="ws_m" value="'+h((s.veh||'').split(' ')[0])+'"></div><div class="f"><label for="ws_o">Modelo</label><input id="ws_o" value="'+h((s.veh||'').split(' ').slice(1).join(' '))+'"></div></div>'+
  '<p class="sm mut">Si el cliente o la patente no existen se crean. Al confirmar se abre WhatsApp con el aviso para el cliente.</p>',
  onOk:()=>{try{const f=val('ws_f'),hr=+val('ws_h'),du=+val('ws_d'),rc=+val('ws_r');if(!f)throw new Error('Elegí la fecha.');const cf=tuConflict(f,hr,du,rc);if(cf)throw new Error(cf);
   const p=val('ws_p').toUpperCase().replace(/[\s-]/g,'');if(!/^([A-Z]{2}\d{3}[A-Z]{2}|[A-Z]{3}\d{3})$/.test(p))throw new Error('Patente inválida (AB123CD o ABC123).');
   let c=cliByTel(s.tel);if(!c){c={id:uid('c'),n:s.n.replace(/ \(ejemplo\)$/,''),tel:String(s.tel).replace(/\D/g,''),mail:'',dom:'',loc:'',prov:'Salta',doc:'',cond:'CF',cc:false,lim:0,saldo:0,club:false,pts:0,nac:'',socio:0};DB.clientes.push(c);audit('Cliente nuevo (menú digital)',c.n)}
   let v=DB.vehs.find(x=>x.pat===p);if(!v){if(!val('ws_m').trim())throw new Error('Cargá la marca del vehículo.');v={id:uid('v'),cliId:c.id,pat:p,marca:val('ws_m').trim(),mod:val('ws_o').trim()||'—',anio:0,km:0,proxKm:0,proxFecha:''};DB.vehs.push(v);audit('Vehículo nuevo',p)}
   DB.seq.tu++;DB.turnos.push({id:'t'+DB.seq.tu,fecha:f,hora:hr,dur:du,rec:rc,cliId:c.id,vehId:v.id,srv:sv.n,estado:'Confirmado',otId:'',web:s.id});s.estado='Confirmada';audit('Turno web confirmado',fdate(f)+' '+hr+':00 · '+sv.n+' · '+c.n);save();
   window.open(waLink(s.tel,'Hola '+c.n.split(' ')[0]+', te confirmamos el turno en '+DB.cfg.nombre+': '+fdate(f)+' a las '+String(hr).padStart(2,'0')+':00 para '+sv.n+' ('+p+'). Dirección: '+DB.cfg.dir+'. ¡Te esperamos!'),'_blank','noopener');
   renderView();renderShellBadge();toast('Turno agendado');return true}catch(e){merr(e.message);return false}}})};
ACT.websolno=d=>{const s=DB.solic.find(x=>x.id===d.id);if(!s)return;confirmBox('¿Rechazar el turno pedido por '+s.n+'? Se abre WhatsApp para avisarle y ofrecerle otro horario.',()=>{s.estado='Rechazada';audit('Turno web rechazado',s.n);save();window.open(waLink(s.tel,'Hola '+s.n.split(' ')[0]+', de '+DB.cfg.nombre+': no tenemos lugar el '+fdate(s.fecha)+' a las '+String(s.hora).padStart(2,'0')+':00. ¿Te sirve otro día u horario?'),'_blank','noopener');renderView();renderShellBadge()},'Rechazar')};
/* catálogo de servicios */
UI.srvArea=UI.srvArea||'';
function webSrvHTML(){const A=UI.srvArea,L=DB.servicios.filter(s=>!A||s.area===A);const ed=isBoss();
 return '<p class="sm mut">Este catálogo es el mismo que se usa en las órdenes de trabajo (precio neto, sin IVA). Lo que está marcado como <b>publicado</b> aparece en el menú digital con el precio final con IVA.'+(ed?'':' Sólo el dueño y el jefe de taller pueden editarlo.')+'</p>'+
 '<div class="chips" style="margin-bottom:8px"><button class="chip'+(!A?' on':'')+'" data-act="srvarea" data-a="">Todas</button>'+AREAS.map(a=>'<button class="chip'+(A===a[0]?' on':'')+'" data-act="srvarea" data-a="'+a[0]+'">'+a[2]+' '+a[1]+'</button>').join('')+'</div>'+
 '<div class="tw"><table class="itbl"><thead><tr><th>Área</th><th>Servicio</th><th>Descripción para el cliente</th><th class="n">Precio neto</th><th>“Desde”</th><th class="n">Horas</th><th class="n">Garantía (meses)</th><th>Publicado</th><th></th></tr></thead><tbody>'+L.map(s=>{const at=f=>' data-chg="srved" data-id="'+s.id+'" data-f="'+f+'"'+(ed?'':' disabled');
  return '<tr><td><select'+at('area')+' style="min-width:120px" aria-label="Área">'+opts(AREAS,s.area,a=>[a[0],a[2]+' '+a[1]])+'</select></td><td><input'+at('n')+' value="'+h(s.n)+'" style="min-width:200px" aria-label="Nombre"></td><td><input'+at('desc')+' value="'+h(s.desc||'')+'" style="min-width:220px" aria-label="Descripción"></td><td><input'+at('pu')+' inputmode="decimal" value="'+s.pu+'" style="width:110px;text-align:right" aria-label="Precio"></td>'+
  '<td class="c"><input type="checkbox"'+at('desde')+(s.desde?' checked':'')+' style="width:auto;min-height:0" aria-label="Precio desde"></td><td><input'+at('h')+' inputmode="decimal" value="'+s.h+'" style="width:64px;text-align:right" aria-label="Horas"></td><td><input'+at('gar')+' inputmode="numeric" value="'+(s.gar||0)+'" style="width:64px;text-align:right" aria-label="Garantía"></td><td class="c"><input type="checkbox"'+at('pub')+(s.pub?' checked':'')+' style="width:auto;min-height:0" aria-label="Publicado"></td>'+
  '<td>'+(ed?'<button class="btn s d" data-act="servdel" data-id="'+s.id+'" aria-label="Quitar">✕</button>':'')+'</td></tr>'}).join('')+'</tbody></table></div>'+
 (ed?'<div class="card" style="margin-top:10px"><h3>Agregar servicio</h3><div class="g4"><div class="f"><label for="ns_a">Área</label><select id="ns_a">'+opts(AREAS,A||'mec',a=>[a[0],a[2]+' '+a[1]])+'</select></div><div class="f"><label for="ns_n">Nombre</label><input id="ns_n" placeholder="Ej.: Instalación de woofer"></div><div class="f"><label for="ns_p">Precio neto</label><input id="ns_p" inputmode="decimal"></div><div class="f"><label for="ns_g">Garantía (meses)</label><input id="ns_g" inputmode="numeric" value="0"></div></div><div class="f"><label for="ns_d">Descripción para el cliente</label><input id="ns_d"></div><button class="btn p" data-act="srvnew">Agregar al catálogo</button></div>':'')}
ACT.srvarea=d=>{UI.srvArea=d.a;renderView()};
CHG.srved=t=>{if(!isBoss())return;const s=srvOf(t.dataset.id);if(!s)return;const f=t.dataset.f;let v=t.type==='checkbox'?t.checked:t.value;
 if(f==='pu'||f==='h'||f==='gar'){v=num(v);if(!(v>=0)||(f==='gar'&&v>120)){t.style.borderColor='var(--bad)';return}}if(f==='n'&&String(v).trim().length<3){t.style.borderColor='var(--bad)';return}
 t.style.borderColor='';const ant=s[f];s[f]=typeof v==='string'?v.trim():v;if(f==='pu'&&ant!==v)audit('Precio de servicio',s.n+': '+fmt(ant)+' → '+fmt(v));save()};
ACT.srvnew=()=>{if(!isBoss())return;const n=val('ns_n').trim(),p=num(val('ns_p')),g=parseInt(val('ns_g'))||0;if(n.length<3){toast('Cargá el nombre del servicio.',1);return}if(!(p>=0)){toast('Precio inválido.',1);return}
 DB.servicios.push({id:uid('s'),area:val('ns_a'),n,pu:p||0,h:1,gar:g,desc:val('ns_d').trim(),desde:false,pub:true});audit('Servicio nuevo',n);save();renderView();toast('Servicio agregado y publicado')};
/* productos publicados */
UI.prdQ=UI.prdQ||'';UI.prdRub=UI.prdRub||'';
function webPrdHTML(){const q=norm(UI.prdQ),R=UI.prdRub;const L=DB.repuestos.filter(r=>r.activo&&(!R||r.rubro===R)&&(!q||norm(r.desc+' '+r.marca+' '+r.cod).includes(q)));const ed=isBoss();
 const pubN=DB.repuestos.filter(r=>r.activo&&r.pub).length;
 return '<p class="sm mut">Elegí qué artículos del inventario se muestran en el menú digital ('+pubN+' publicados). El menú muestra el precio final con IVA y si hay stock (“Disponible”, “Últimas unidades” o “Sin stock”), nunca la cantidad ni el costo.</p>'+
 '<div class="row" style="margin-bottom:8px"><input id="prq" style="max-width:260px" placeholder="Buscar artículo…" value="'+h(UI.prdQ)+'" data-chg="prdq" aria-label="Buscar"><select style="max-width:220px" data-chg="prdrub" aria-label="Rubro">'+opts(DB.rubrosRep,R,null,'Todos los rubros')+'</select>'+(ed?'<button class="btn s" data-act="prdall" data-v="1">Publicar los filtrados</button><button class="btn s" data-act="prdall" data-v="0">Despublicar los filtrados</button>':'')+'</div>'+
 '<div class="tw"><table class="itbl"><thead><tr><th>Publicado</th><th>Artículo</th><th>Rubro</th><th class="n">Precio final</th><th>Stock</th><th class="n">Garantía (meses)</th><th>Destacado</th></tr></thead><tbody>'+L.slice(0,300).map(r=>'<tr><td class="c"><input type="checkbox" data-chg="prdpub" data-id="'+r.id+'"'+(r.pub?' checked':'')+(ed?'':' disabled')+' style="width:auto;min-height:0" aria-label="Publicar '+h(r.desc)+'"></td><td>'+h(r.desc)+' <span class="mut sm">'+h(r.marca+' · '+r.cod)+'</span></td><td class="sm">'+h(r.rubro)+'</td><td class="n">'+fmt(precioFinal(r.pv,r.iva))+'</td><td>'+stockTag(r).replace('class="tag','class="badge')+'</td><td><input data-chg="prdgar" data-id="'+r.id+'" inputmode="numeric" value="'+(r.gar||0)+'" style="width:64px;text-align:right"'+(ed?'':' disabled')+' aria-label="Garantía"></td><td class="c"><input type="checkbox" data-chg="prddest" data-id="'+r.id+'"'+(r.dest?' checked':'')+(ed?'':' disabled')+' style="width:auto;min-height:0" aria-label="Destacado"></td></tr>').join('')+(L.length?'':'<tr><td colspan="7" class="mut c">Sin resultados.</td></tr>')+'</tbody></table></div>'}
CHG.prdq=t=>{UI.prdQ=t.value;const p=t.selectionStart;renderView();const n=$('#prq');if(n){n.focus();try{n.setSelectionRange(p,p)}catch(e){}}};
CHG.prddest=t=>{if(!isBoss())return;const r=repOf(t.dataset.id);if(r){r.dest=t.checked;save()}};
CHG.prdrub=t=>{UI.prdRub=t.value;renderView()};
CHG.prdpub=t=>{if(!isBoss())return;const r=repOf(t.dataset.id);if(r){r.pub=t.checked;save()}};
CHG.prdgar=t=>{if(!isBoss())return;const r=repOf(t.dataset.id);const v=parseInt(t.value);if(r&&v>=0&&v<=120){r.gar=v;t.style.borderColor='';save()}else t.style.borderColor='var(--bad)'};
ACT.prdall=d=>{if(!isBoss())return;const q=norm(UI.prdQ),R=UI.prdRub;let n=0;DB.repuestos.forEach(r=>{if(r.activo&&(!R||r.rubro===R)&&(!q||norm(r.desc+' '+r.marca+' '+r.cod).includes(q))){r.pub=d.v==='1';n++}});audit('Menú: publicación masiva',(d.v==='1'?'publicados ':'despublicados ')+n);save();renderView()};
function webCfgHTML(){const M=DB.cfg.menu,ed=isBoss();const at=f=>' data-chg="menucfg" data-f="'+f+'"'+(ed?'':' disabled');
 return '<div class="card"><h3>Lo que ve el cliente</h3><p class="sm mut">El nombre, la dirección, el WhatsApp y las redes salen de Configuración → Datos del taller.</p><div class="f"><label for="mc_b">Frase de bienvenida</label><input id="mc_b"'+at('bienvenida')+' value="'+h(M.bienvenida)+'"></div><div class="f"><label for="mc_h">Horarios de atención</label><input id="mc_h"'+at('horario')+' value="'+h(M.horario)+'"></div>'+
 [['precios','Mostrar precios (si se apaga, dice “Consultar”)'],['turnos','Permitir pedir turno desde el menú'],['club','Mostrar el Club y la alta de socios']].map(x=>'<label style="font-weight:500;color:var(--tx);display:block;margin-top:6px"><input type="checkbox" style="width:auto;min-height:0"'+at(x[0])+(M[x[0]]?' checked':'')+'> '+x[1]+'</label>').join('')+'</div>'+
 '<div class="card"><h3>Cómo lo comparten</h3><p class="sm">Enlace del menú: <b>'+h(menuURL())+'</b></p><p class="sm mut">Se puede poner en la biografía de Instagram, en el estado de WhatsApp o en un cartel con QR en el mostrador [el QR se genera con cualquier generador gratuito a partir de este enlace].</p></div>'}
CHG.menucfg=t=>{if(!isBoss())return;DB.cfg.menu[t.dataset.f]=t.type==='checkbox'?t.checked:t.value.trim();save()};

/* ======================= Club y fidelización (sistema) ======================= */
UI.clubTab=UI.clubTab||'soc';UI.clubQ=UI.clubQ||'';
V.club=()=>{const T=UI.clubTab,K=DB.cfg.club;const tabs=[['soc','Socios'],['rec','Recordatorios'],['pre','Premios'],['mov','Movimientos'],['cfg','Reglas del Club']];
 let b=T==='soc'?clubSocHTML():T==='rec'?clubRecHTML():T==='pre'?clubPreHTML():T==='mov'?clubMovHTML():clubCfgHTML();
 const so=DB.clientes.filter(c=>c.club),pts=so.reduce((a,c)=>a+(c.pts||0),0);
 return '<div class="bar"><h2>Club y fidelización</h2><span class="sp"></span><span class="mut sm">'+so.length+' socios · '+pts+' puntos en circulación ('+fmt(ptsPesos(pts))+')</span><button class="btn p" data-act="clubnew">➕ Sumar socio</button></div>'+
 (K.on?'':'<div class="demoflag">El Club está apagado: no se suman puntos. Encendelo en “Reglas del Club”.</div>')+
 '<div class="chips" style="margin-bottom:10px">'+tabs.map(t=>'<button class="chip'+(T===t[0]?' on':'')+'" data-act="clubtab" data-t="'+t[0]+'">'+t[1]+'</button>').join('')+'</div>'+b};
ACT.clubtab=d=>{UI.clubTab=d.t;renderView()};
function clubSocHTML(){const q=norm(UI.clubQ);const L=DB.clientes.filter(c=>c.club&&(!q||norm(c.n+' '+c.tel+' '+socioNum(c)).includes(q))).sort((a,b)=>a.socio-b.socio);
 return '<input id="clq" style="max-width:280px;margin-bottom:8px" placeholder="Buscar socio, teléfono o N.º…" value="'+h(UI.clubQ)+'" data-chg="clubq" aria-label="Buscar socio">'+
 '<div class="tw"><table><thead><tr><th>Socio</th><th>Nombre</th><th>Nivel</th><th class="n">Puntos</th><th>Cumpleaños</th><th></th></tr></thead><tbody>'+L.map(c=>{const N=nivelOf(c);return '<tr><td>'+socioNum(c)+'</td><td><b>'+h(c.n)+'</b><br><span class="sm mut">'+h(c.tel)+'</span></td><td><span class="badge '+(N.lv.n==='Oro'?'warn':N.lv.n==='Plata'?'':'ok')+'">'+h(N.lv.n)+'</span></td><td class="n"><b>'+(c.pts||0)+'</b><br><span class="sm mut">'+fmt(ptsPesos(c.pts))+'</span></td><td>'+(c.nac?fdate(c.nac).slice(0,5):'—')+'</td>'+
  '<td><div class="row"><button class="btn s" data-act="clubcard" data-id="'+c.id+'">Tarjeta</button><button class="btn s" data-act="clubcanje" data-id="'+c.id+'">Canjear</button><button class="btn s" data-act="clubajuste" data-id="'+c.id+'">Ajustar</button>'+(c.tel?'<a class="btn s" target="_blank" rel="noopener" href="'+h(waLink(c.tel,'Hola '+c.n.split(' ')[0]+'! Sos socio '+socioNum(c)+' del Club de '+DB.cfg.nombre+': tenés '+(c.pts||0)+' puntos (nivel '+N.lv.n+'). Mirá tu tarjeta y los premios en '+menuURL()))+'">💬</a>':'')+'</div></td></tr>'}).join('')+(L.length?'':'<tr><td colspan="6" class="mut c">Sin socios.</td></tr>')+'</tbody></table></div>'}
CHG.clubq=t=>{UI.clubQ=t.value;const p=t.selectionStart;renderView();const n=$('#clq');if(n){n.focus();try{n.setSelectionRange(p,p)}catch(e){}}};
ACT.clubnew=()=>{const L=DB.clientes.filter(c=>!c.club);modal({title:'Sumar socio al Club',ok:'Sumar',body:(L.length?'<div class="f"><label for="cn_c">Cliente</label><select id="cn_c">'+opts(L.slice().sort((a,b)=>a.n.localeCompare(b.n)),'',c=>[c.id,c.n+(c.tel?' · '+c.tel:'')],'— elegir —')+'</select></div>':'<p class="mut">Todos los clientes ya son socios. Creá el cliente en “Clientes y vehículos”.</p>')+
 '<div class="f"><label for="cn_n">Fecha de nacimiento</label><input type="date" id="cn_n"></div><label style="font-weight:500;color:var(--tx)"><input type="checkbox" id="cn_ok" style="width:auto;min-height:0"> El cliente acepta sumarse al Club y recibir avisos por WhatsApp (puede darse de baja cuando quiera)</label>',
 onOk:()=>{const c=cliOf(val('cn_c'));if(!c){merr('Elegí el cliente.');return false}const n=val('cn_n');if(n&&edad(n)<18){merr('El Club es para mayores de 18 años.');return false}if(!chk('cn_ok')){merr('Falta el consentimiento del cliente.');return false}
  hacerSocio(c,n);save();renderView();toast(c.n+' es socio '+socioNum(c));return true}})};
ACT.clubajuste=d=>{const c=cliOf(d.id);if(!c)return;if(!isBoss()){toast('Los ajustes los hacen el dueño o el jefe de taller.',1);return}modal({title:'Ajustar puntos · '+c.n,ok:'Registrar ajuste',body:'<p>Saldo actual: <b>'+(c.pts||0)+' puntos</b></p><div class="g2"><div class="f"><label for="aj_p">Puntos (+ suma, − resta)</label><input id="aj_p" inputmode="numeric" placeholder="Ej.: 50 o -20"></div><div class="f"><label for="aj_m">Motivo</label><input id="aj_m" placeholder="Corrección, promoción…"></div></div>',
 onOk:()=>{const p=parseInt(val('aj_p'));if(!p){merr('Ingresá los puntos.');return false}if(val('aj_m').trim().length<3){merr('Indicá el motivo.');return false}if((c.pts||0)+p<0){merr('El saldo no puede quedar negativo.');return false}ptsMov(c,'Ajuste',p,val('aj_m').trim());audit('Club: ajuste de puntos',c.n+' '+(p>0?'+':'')+p+' · '+val('aj_m').trim());save();renderView();return true}})};
ACT.clubcanje=d=>{const c=cliOf(d.id);if(!c)return;const P=DB.premios.filter(p=>p.pts>0);
 modal({title:'Canjear premio · '+c.n,ok:'Canjear',body:'<p>Saldo: <b>'+(c.pts||0)+' puntos</b>. Para usar los puntos como pago en una orden, elegí “Canje de puntos del Club” al cobrar y entregar el vehículo ('+fmt(DB.cfg.club.valor)+' por punto).</p>'+
  (P.length?'<div class="f"><label for="cj_p">Premio</label><select id="cj_p">'+P.map(p=>'<option value="'+p.id+'"'+(p.pts>(c.pts||0)?' disabled':'')+'>'+h(p.n+' · '+p.pts+' pts'+(p.pts>(c.pts||0)?' (le faltan '+(p.pts-(c.pts||0))+')':''))+'</option>').join('')+'</select></div>':'<p class="mut">No hay premios cargados.</p>'),
  onOk:()=>{const p=DB.premios.find(x=>x.id===val('cj_p'));if(!p){merr('Elegí un premio.');return false}if(p.pts>(c.pts||0)){merr('No le alcanzan los puntos.');return false}ptsMov(c,'Canje',-p.pts,p.n);audit('Club: canje de premio',c.n+' · '+p.n+' (−'+p.pts+')');save();renderView();
   if(c.tel)window.open(waLink(c.tel,'¡Hola '+c.n.split(' ')[0]+'! Canjeaste "'+p.n+'" con '+p.pts+' puntos en '+DB.cfg.nombre+'. Te quedan '+c.pts+' puntos.'),'_blank','noopener');toast('Canje registrado');return true}})};
function clubCardHTML(c,pub){const N=nivelOf(c),K=DB.cfg.club;const pct=N.nx?Math.min(100,Math.round(N.acum/N.nx.d*100)):100;
 return '<div class="clubcard '+h(N.lv.n)+'"><div class="row" style="justify-content:space-between"><b>'+h(DB.cfg.nombre)+'</b><span class="sm">Club · '+h(N.lv.n)+'</span></div><div style="margin:14px 0 6px" class="sm">'+h(pub?c.n.split(' ')[0]:c.n)+' · Socio '+socioNum(c)+'</div><div class="big">'+(c.pts||0)+' <span style="font-size:1rem;font-weight:600">puntos</span></div><div class="sm">Equivalen a '+fmt(ptsPesos(c.pts))+' para usar en el taller</div>'+
 '<div class="lvbar"><span style="width:'+pct+'%"></span></div><div class="sm" style="margin-top:4px">'+(N.nx?'Te faltan '+Math.max(0,N.nx.d-N.acum)+' puntos para '+h(N.nx.n):'Nivel máximo')+'</div><div class="sm" style="margin-top:6px">'+h(N.lv.b)+'</div></div>'}
