 const s=srvOf(sid);DB.seq.sol=(DB.seq.sol||0)+1;DB.solic.unshift({id:uid('sw'),num:DB.seq.sol,t:Date.now(),fecha:f,hora:hr,sid,n,tel:t,pat:p,veh:val('pt_v').trim().slice(0,60),nota:val('pt_x').trim().slice(0,200),estado:'Nueva'});save();
